type robotsRule struct {
	groups  map[string][]*regexp.Regexp // user-agent(小写) -> disallow 模式；"*" 为默认组
	fetched time.Time
}

// New 创建 Fetcher。
func New(opts Options) *Fetcher {
	if opts.UserAgent == "" {
		opts.UserAgent = "news-report/1.0 (news aggregator)"
	}
	if opts.Timeout <= 0 {
		opts.Timeout = 15 * time.Second
