		return s
	}
	return string(r[:n]) + "…"
}

// sourceWeight 查表来源权重（未知来源给默认 0.8）。
func sourceWeight(id string, list []sources.Source) float64 {
	for _, s := range list {
		if s.ID == id {
			return s.Weight
		}
	}
	return 0.8
}

